    IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_namespace n
        CROSS JOIN LATERAL pg_catalog.aclexplode(n.nspacl) a
        WHERE n.nspname = 'offline_crypto' AND a.grantee = owner_role.oid
          AND a.privilege_type = 'USAGE' AND NOT a.is_grantable
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.pg_namespace n
