        UNION SELECT a.grantee FROM pg_catalog.pg_class c CROSS JOIN LATERAL
            pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a WHERE c.oid=ANY(relation_oids)
